"""Protocol definition and backend registry for Bedrock cache backends."""

from __future__ import annotations

from collections.abc import Awaitable, Callable
from typing import Protocol

from pydantic_settings import BaseSettings


class CacheBackend(Protocol):
    """Protocol that all cache backends must implement.

    Backends store raw ``bytes``. All serialization/deserialization
    is handled by :class:`CacheService` and shared across backends.
    Both sync and async variants are required.

    Clients are created at ``__init__`` time.
    """

    @property
    def settings(self) -> BaseSettings: ...

    def get(self, key: str, default: bytes | None = None) -> bytes | None: ...
    async def aget(self, key: str, default: bytes | None = None) -> bytes | None: ...

    def set(
        self, key: str, value: bytes, ex: int | None = None, px: int | None = None, ea: float | None = None
    ) -> None: ...
    async def aset(
        self, key: str, value: bytes, ex: int | None = None, px: int | None = None, ea: float | None = None
    ) -> None: ...

    def add(
        self, key: str, value: bytes, ex: int | None = None, px: int | None = None, ea: float | None = None
    ) -> bool: ...
    async def aadd(
        self, key: str, value: bytes, ex: int | None = None, px: int | None = None, ea: float | None = None
    ) -> bool: ...

    def delete(self, key: str) -> bool: ...
    async def adelete(self, key: str) -> bool: ...

    def compare_and_delete(self, key: str, expected: bytes) -> bool: ...
    async def acompare_and_delete(self, key: str, expected: bytes) -> bool: ...

    def exists(self, key: str) -> bool: ...
    async def aexists(self, key: str) -> bool: ...

    def get_with_ttl(self, key: str) -> tuple[bytes | None, int | None]: ...
    async def aget_with_ttl(self, key: str) -> tuple[bytes | None, int | None]: ...

    def clear(self, prefix: str | None = None) -> int: ...
    async def aclear(self, prefix: str | None = None) -> int: ...

    def get_many(self, keys: list[str]) -> dict[str, bytes]: ...
    async def aget_many(self, keys: list[str]) -> dict[str, bytes]: ...

    def set_many(
        self, mapping: dict[str, bytes], ex: int | None = None, px: int | None = None, ea: float | None = None
    ) -> None: ...
    async def aset_many(
        self, mapping: dict[str, bytes], ex: int | None = None, px: int | None = None, ea: float | None = None
    ) -> None: ...

    def get_or_set(
        self,
        key: str,
        default_provider: Callable[[], bytes] | bytes,
        ex: int | None = None,
        px: int | None = None,
        ea: float | None = None,
    ) -> bytes | None: ...
    async def aget_or_set(
        self,
        key: str,
        default_provider: Callable[[], bytes] | bytes | Callable[[], Awaitable[bytes]],
        ex: int | None = None,
        px: int | None = None,
        ea: float | None = None,
    ) -> bytes | None: ...

    def list(self, prefix: str, limit: int = 100) -> list[str]: ...
    async def alist(self, prefix: str, limit: int = 100) -> list[str]: ...

    def incr(self, key: str, delta: int = 1) -> int: ...
    async def aincr(self, key: str, delta: int = 1) -> int: ...

    def decr(self, key: str, delta: int = 1) -> int: ...
    async def adecr(self, key: str, delta: int = 1) -> int: ...

    def close(self) -> None: ...
    async def aclose(self) -> None: ...
